"""Pensamiento Computacional EPJA Media N1 y N2, módulo 3 (parte): OAD-09 y OAD-10, la repetición «hasta que» aplicada a la funcionalidad de un objeto; OAD-11 y OAD-12, bases de datos como oportunidad y su transferencia a estructuras de varias tablas. Todo en papel, sin computador; datos inventados."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = ("Papel, lápiz y goma. Todo se resuelve en papel y sin computador ni celular: los algoritmos se escriben en seudocódigo, "
             "en diagramas de flujo escritos y en tablas de seguimiento. Los objetos, tablas y cifras son de ejemplo, inventados.")
build = make_build(MATERIALS)

O9 = "EPJA-PECO-NM1y2-OAD-09"
O10 = "EPJA-PECO-NM1y2-OAD-10"
O11 = "EPJA-PECO-NM1y2-OAD-11"
O12 = "EPJA-PECO-NM1y2-OAD-12"
PRIOR = ["Ya sigo pasos en mi vida diaria, como una receta, un trámite o el manual de un artefacto.",
         "Sé que algunas tareas se repiten hasta lograr un resultado, como amasar, llenar un balde o esperar un turno."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_, prior=None):
    build(oa, n, F, use=use, prior=prior or PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes,
          T=T, ctx=ctx, sc=sc, op=op, reinforce=rf, extend=ex_)


