  [("Repetir el sector del cliente en cada pedido.", "Si el dato cambia, hay que corregir muchas filas y pueden quedar versiones distintas.", "Guarda el dato una vez en Clientes y conecta con la clave."),
   ("Pensar que cada cliente tiene un solo pedido.", "Se confunde la relación uno a muchos con una relación uno a uno.", "Un cliente puede aparecer en varias filas de Pedidos.")],
